from py2pddl import Domain, create_type
from py2pddl import predicate, action

class BlocksWorldDomain(Domain):
    Block = create_type("block")

    @predicate(Block)
    def clear(self, b):
        """Block is clear (no blocks on top and not held)"""

    @predicate(Block, Block)
    def on(self, b, under):
        """Block b is on top of block under"""

    @predicate(Block)
    def on_table(self, b):
        """Block is on the table"""

    @predicate(Block)
    def holding(self, b):
        """Block is being held"""

    @predicate()
    def hand_empty(self):
        """Hand is empty"""

    @action(Block)
    def pickup(self, b):
        precond = [
            self.hand_empty(),
            self.clear(b),
            self.on_table(b)
        ]
        effect = [
            ~self.hand_empty(),
            self.holding(b),
            ~self.on_table(b),
            ~self.clear(b)
        ]
        return precond, effect

